-- evt:disc
RegisterEvent(15, "Darzog's disc", function()
    if not (IsQBitSet(QBit(110500))) then
        evt.SimpleMessage("A disc of black stone hangs in the Well behind this grille, the Baron's rune glowing on its rim. It answers to Darzog alone while he lives.")
        return
    end
    if IsAtLeast(MapVar(6), 1) then
        evt.SetDoorState(32, DoorAction.Close)
        evt.SetDoorState(13, DoorAction.Open)
        SetValue(MapVar(6), 0)
    else
        evt.SetDoorState(13, DoorAction.Close)
        evt.SetDoorState(32, DoorAction.Open)
        SetValue(MapVar(6), 1)
    end
    evt.StatusText("The disc hums and glides along the Well.", 4)
end, "Darzog's disc")

